FUNCTION handleDeleteActuator(request, actuator_id):
    // REQ-2-016; Preconditions: persistence available. REQUIRE admin or RETURN 401/403.
    IF actuator_id <= 0 OR absent THEN RETURN 404. BEGIN TRANSACTION.
    IF referenced by action or command THEN ROLLBACK; RETURN 409 under REQ-2-009. END IF DELETE actuator; COMMIT; RETURN 204.
    // Repeat returns 404; rollback preserves every relation on error.

FUNCTION handleDeleteRule(request, rule_id):
    // REQ-2-023; Preconditions: persistence available. REQUIRE owner/admin or RETURN 401/403.
    IF rule_id <= 0 OR absent THEN RETURN 404. BEGIN TRANSACTION.
    IF any execution exists THEN ROLLBACK; RETURN 409 under REQ-2-009. END IF DELETE action definitions then rule; COMMIT; RETURN 204.
    // Repeat returns 404; any error rolls back and preserves rule/actions/audit history.

FUNCTION handleListActuators(request):
    // REQ-2-012; Preconditions: persistence available. REQUIRE authenticated user/admin or RETURN 401.
    VALIDATE filters and pagination or RETURN 422. IF owner_id <= 0 OR absent THEN RETURN 404. END IF
    IF caller is user and owner_id is another user THEN RETURN 403. END IF
    READ visible filtered actuators, sort id ascending, page, RETURN 200.
    // Transaction: none; postcondition: actuators, rules, commands, events, executions unchanged.

FUNCTION handleListActuatorCommands(request, actuator_id):
    // REQ-2-018; Preconditions: persistence available. REQUIRE owner/admin or RETURN 401/403.
    IF actuator_id <= 0 OR absent THEN RETURN 404. VALIDATE origin and pagination or RETURN 422.
    READ matching immutable commands by id page; RETURN 200.
    // Transaction: none; postcondition: command and actuator state remain unchanged.

FUNCTION handleListExecutions(request):
    // REQ-2-027; Preconditions: persistence available. REQUIRE authenticated caller or RETURN 401.
    VALIDATE filters and pagination or RETURN 422; IF rule_id is non-positive or absent THEN RETURN 404.
    IF user caller does not own selected rule THEN RETURN 403. READ owner-visible immutable executions, sort id, page, RETURN 200.
    // Transaction: none; postcondition: events, executions, commands, actuators, and rules remain unchanged.

FUNCTION handleListRules(request):
    // REQ-2-019; Preconditions: persistence available. REQUIRE authenticated caller or RETURN 401.
    VALIDATE filters and pagination or RETURN 422; reject invalid owner_id with 404 and other-user owner query with 403.
    READ caller-owned or admin-visible rules, ascending id page; RETURN 200.
    // Transaction: none; postcondition: all records unchanged.

FUNCTION handleGetRule(request, rule_id):
    // REQ-2-021; Preconditions: persistence available. REQUIRE authenticated caller or RETURN 401.
    IF rule_id <= 0 OR absent THEN RETURN 404. IF user caller is not owner THEN RETURN 403. END IF
    READ rule plus actions ordered by action.order; RETURN 200.
    // Transaction: none; postcondition: persistent state unchanged.

FUNCTION handleGetHealth(request):
    // REQ-2-011; Preconditions: none. Authorization: public. Transaction: none.
    IF local persistence probe fails THEN RETURN 503. END IF
    RETURN 200 with status = ok.
    // Postcondition: every persistent domain record is unchanged.

FUNCTION handlePatchActuator(request, actuator_id):
    // REQ-2-015; Preconditions: JSON and persistence available. REQUIRE admin or RETURN 401/403; REQUIRE JSON or RETURN 415.
    IF actuator_id <= 0 OR absent THEN RETURN 404. Parse or RETURN 400; VALIDATE resulting non-empty patch and owner or RETURN 422.
    BEGIN TRANSACTION; update supplied metadata only; COMMIT; RETURN 200.
    // Identical valid patch is idempotent. On error rollback preserves actuator, rules, commands, events, executions.

FUNCTION handleCreateActuator(request):
    // REQ-2-013; Preconditions: JSON and persistence available. REQUIRE admin or RETURN 401/403.
    REQUIRE application/json or RETURN 415; parse JSON or RETURN 400; VALIDATE REQ-2-001/-002 or RETURN 422.
    IF owner_id <= 0 OR owner absent THEN RETURN 404. BEGIN TRANSACTION. IF serial exists THEN ROLLBACK; RETURN 409. END IF
    CREATE actuator with initial_value; COMMIT; RETURN 201 with Location.
    // Non-idempotent; errors roll back and leave all relations unchanged.

FUNCTION handleCreateManualCommand(request, actuator_id):
    // REQ-2-017; Preconditions: JSON, positive actuator, persistence available. REQUIRE owner/admin or RETURN 401/403.
    REQUIRE JSON or RETURN 415; parse or RETURN 400; VALIDATE value for type under REQ-2-002 or RETURN 422.
    BEGIN TRANSACTION; CREATE MANUAL APPLIED command; update actuator.current_value; COMMIT; RETURN 201 with Location.
    // REQ-2-008. Non-idempotent; rollback keeps actuator and command history unchanged.

FUNCTION handleCreateAutomationEvent(request):
    // REQ-2-026; Preconditions: JSON and persistence available. REQUIRE authenticated caller or RETURN 401; REQUIRE JSON or RETURN 415; parse or RETURN 400.
    RESOLVE authorized owner; VALIDATE event or RETURN 422. BEGIN TRANSACTION; lock owner event key.
    IF same client_event_id exists with identical payload THEN COMMIT; RETURN 200 prior result. IF same key differs THEN ROLLBACK; RETURN 409. END IF
    CREATE event; evaluate matching enabled rules id ascending; create APPLIED/SUPPRESSED executions and commands atomically; COMMIT; RETURN 201 Location.
    // Errors roll back event, executions, commands, and actuator values together.

FUNCTION handleCreateRule(request):
    // REQ-2-020; Preconditions: JSON and persistence available. REQUIRE authenticated caller or RETURN 401; REQUIRE JSON or RETURN 415; parse or RETURN 400.
    RESOLVE owner: caller for user, explicit existing positive owner for admin; reject forbidden owner choice with 403/404. VALIDATE rule/actions or RETURN 422.
    BEGIN TRANSACTION; verify action actuators exist and same owner; if name duplicate ROLLBACK RETURN 409; CREATE rule/actions; COMMIT RETURN 201 Location.
    // Non-idempotent. Rollback preserves all rules, actuators, commands, events, and executions.

FUNCTION handleDisableRule(request, rule_id):
    // REQ-2-025; Preconditions: persistence available. REQUIRE owner/admin or RETURN 401/403.
    IF rule_id <= 0 OR absent THEN RETURN 404. BEGIN TRANSACTION; SET enabled = false; COMMIT; RETURN 200.
    // Idempotent. Rollback preserves all rule relations; disabled rule will not execute under REQ-2-006.

FUNCTION handleEnableRule(request, rule_id):
    // REQ-2-024; Preconditions: persistence available. REQUIRE owner/admin or RETURN 401/403.
    IF rule_id <= 0 OR absent THEN RETURN 404. BEGIN TRANSACTION; SET enabled = true; COMMIT; RETURN 200.
    // Idempotent. On error rollback preserves rule, actions, commands, and executions.

FUNCTION handleReplaceRule(request, rule_id):
    // REQ-2-022; Preconditions: JSON, positive existing rule, persistence available. REQUIRE owner/admin or RETURN 401/403.
    REQUIRE JSON or RETURN 415; parse or RETURN 400; VALIDATE complete replacement and same-owner actuators or RETURN 422/404.
    BEGIN TRANSACTION; if different rule has same owner/name ROLLBACK RETURN 409; REPLACE action definitions; update rule; COMMIT RETURN 200.
